If you have questions about GDPR compliance or need a Data Processing Agreement (DPA) signed, you can reach out via intercom or email at support@qwary.com[3]. Individuals have the right to know how their data is being used, export it, or request that it be deleted, and there is a form available to make a data request[3].', '{"trace": {"filters": {"spaces": ["QWARY_HELP"], "doc_types": [], "labels_any": [], "principals": ["group:all-staff"], "labels_none": [], "updated_after": null, "updated_before": null}, "refusal": null, "channels": [{"top": ["https://help.qwary.com/product-guide/faq/gdpr-compliance", "https://help.qwary.com/product-guide/compose-survey/website-feedback-button", "https://help.qwary.com/product-guide/closed-feedback-loop/rule-based-email-notifications", "https://help.qwary.com/product-guide/launch-survey/website-feedback", "https://help.qwary.com/product-guide"], "hits": 20, "error": null, "channel": "pgp", "latency_ms": 2822.6}, {"top": ["https://help.qwary.com/product-guide/faq/gdpr-compliance"], "hits": 1, "error": null, "channel": "ecm", "latency_ms": 166.09}], "degraded": [], "phase_ms": {"prime": 285.9, "rerank": 0.8, "resolve": 0.3, "passages": 3, "candidates": 2824.3, "resolve_batch": 87.6, "embed_question": 999.7}, "synonyms": {}, "total_ms": 4201.74, "plan_hash": "pln_4bfcf6fc2b512da2", "spec_json": "{\"authority\":\"include_supporting\",\"channels\":[\"pgp\",\"ecm\"],\"diversity_by\":\"document\",\"doc_types\":[],\"filters\":[],\"freshness\":{\"as_of\":null,\"max_age_days\":null},\"intent\":\"lookup\",\"k_per_channel\":20,\"question\":\"GDPR Compliance\",\"scope_ref\":\"scope:cn-qwary-help:v6\",\"terms\":[]}", "candidates": [{"title": "GDPR Compliance", "doc_id": "https://help.qwary.com/product-guide/faq/gdpr-compliance", "authority": "supporting", "cache_hit": true, "staleness": "fresh", "dropped_by": null, "parse_path": "html_trafilatura", "resolution": "resolved", "drop_detail": null, "fusion_rank": 1, "rerank_rank": 3, "fusion_score"