INSERT INTO "aai"."askcontent_chat_turn" ("id", "org_id", "thread_id", "ordinal", "question", "answer", "evidence", "steps", "grounded", "unsupported_reason", "answered_by", "elapsed_ms", "error", "created_at", "updated_at") VALUES ('d6460007-4b7a-4b16-8cfc-b34f01bfda9a', '9a76da8a-4934-4a60-838d-ca2bf689bd38', '09176a67-42ae-4665-8255-a59f29acdf0b', 2, 'How do I close a checking or savings account?', 'You can close a checking or savings account by contacting Wells Fargo in one of the following ways:

1. Call Wells Fargo at 1-800-TO-WELLS (1-800-869-3557) [1].
2. Visit a Wells Fargo branch near you [1].
3. If you are outside of the U.S., complete the Account Closure or Partial Withdrawal Request form (PDF) and send it by mail [1].

You can request to close your account anytime. Most accounts can be closed immediately if:

- The account has a positive or zero balance [1].
- All deposits, outstanding, and pending items are posted [1].

Before closing your account, you should:

- Cancel any recurring payments or withdrawals (such as bill payments and debit card payments), as these may be returned unpaid after closure and the payee or merchant may charge fees for returned items [2].

Accounts with a zero balance will continue to be charged applicable fees (like the monthly service fee) until you request to close your account [2].

Conditions that may prevent closure include:

- Prime Checking and Premier Checking accounts that need to process a statement; the statement will be finalized no later than the third business day of the month [3].
- Legal or bank restrictions that need to be resolved [3].
- Funds pledged for collateral or other purposes that need to be released [3].
- Balance sweep feature needs to be removed [3].
