INSERT INTO "aai"."askcontent_chat_turn" ("id", "org_id", "thread_id", "ordinal", "question", "answer", "evidence", "steps", "grounded", "unsupported_reason", "answered_by", "elapsed_ms", "error", "created_at", "updated_at") VALUES ('c2e95e9c-3ca0-483f-9114-4983ffa8ecc5', '9a76da8a-4934-4a60-838d-ca2bf689bd38', 'ff987c17-f718-4121-b094-2ee1d4152414', 3, 'What should I know about Personal Loan Help?', 'Personal Loan Help covers information about repayment terms, application tracking, automatic payments, and considerations for debt consolidation:

## Repayment Terms

- A representative example for an unsecured personal loan: For $17,000 borrowed over 48 months at 13.99% Annual Percentage Rate (APR), the monthly payment is $464. This is an estimate only and assumes all payments are made on time[1][3].

## Application Process and Tracking

- You could receive a quick credit decision, typically the same day[2].
- For most applications, you can track your application status online if you provide your email address at the time of application. Wells Fargo will send you an email with instructions on how to do this[2][6].

## Automatic Payments

- With automatic payments, your payment is debited monthly from your checking or savings account[2].
- To set up automatic payments:
  1. Sign on to your Wells Fargo account[2].
  2. Select your auto loan from **Account Summary**[2].
  3. Select **Set up Autopay**[2].
  4. Alternatively, you can call 1-800-289-8004 or download the automatic loan payments authorization (PDF), complete it, and return it by mail or fax[2].
- If you want to change your automatic payment, you must cancel the recurring schedule and set up Autopay again[5].
- To cancel automatic payments:
  1. Sign on to your account[5].
  2. Select your auto loan from **Account Summary**[5].
  3. Select **Manage Autopay**[5].
  4. Allow at least 3 business days before the automatic payment is scheduled to withdraw[5].

## Statements

- As an Online Banking customer, you can view, download, and print up to 12 months of auto loan statements[5].
- To stop receiving paper statements, sign on and select **Manage delivery preferences**[5].

## Debt Consolidation Considerations

- Before applying, consider whether consolidating your existing debt is the right choice for you. Consolidating multiple debts means you will have a single monthly payment, but it may not reduce or pay your debt off sooner. The payment reduction may come from a lower interest rate, a longer loan term, or a combination of both[3].

## Deposit Products

- Deposit products are offered by Wells Fargo Bank, N.A., Member FDIC[4].', '{"trace": {"filters": {"spaces": ["WELLSFARGO_HELP_CENTER"], "doc_types": [], "labels_any": [], "principals": ["group:all-staff"], "labels_none": [], "updated_after": null, "updated_before": null}, "refusal": null, "channels": [{"top": ["https://www.wellsfargo.com/help/loans", "https://www.wellsfargo.com/help/loans/personal-loan-faqs/?sub_channel=WEB&vendor_code=WF&linkloc=FNPLFAQ", "https://www.wellsfargo.com/help/contact-us", "https://www.wellsfargo.com/help/home-lending", "https://www.wellsfargo.com/help/loans/auto-loans-faqs"], "hits": 16, "error": null, "channel": "pgp", "latency_ms": 1260.42}, {"top": ["https://www.wellsfargo.com/help/loans", "https://www.wellsfargo.com/help/loans/personal-loan-faqs/?sub_channel=WEB&vendor_code=WF&linkloc=FNPLFAQ", "https://www.wellsfargo.com/help/checking-savings", "https://www.wellsfargo.com/help/credit-cards", "https://www.wellsfargo.com/help/home-lending"], "hits": 10, "error": null, "channel": "ecm", "latency_ms": 248.16}], "degraded": [], "phase_ms": {"prime": 0, "rerank": 1, "resolve": 0.2, "passages": 11.3, "candidates": 1261.4, "resolve_batch": 85.6, "embed_question": 152.5}, "synonyms": {}, "total_ms": 1513.32, "plan_hash": "pln_71b947587e736201", "spec_json": "{\"authority\":\"include_supporting\",\"channels\":[\"pgp\",\"ecm\"],\"diversity_by\":\"document\",\"doc_types\":[],\"filters\":[],\"freshness\":{\"as_of\":null,\"max_age_days\":null},\"intent\":\"lookup\",\"k_per_channel\":20,\"question\":\"What should I know about Personal Loan Help?\",\"scope_ref\":\"scope:cn-wells-fargo-help-centre:v1\",\"terms\":[]}", "candidates": [{"title": "Personal Loan Help | Wells Fargo", "doc_id": "https://www.wellsfargo.com/help/loans", "authority": "supporting", "cache_hit": true, "staleness": "unknown_age", "dropped_by": null, "parse_path": "html_trafilatura", "resolution": "resolved", "drop_detail": null, "fusion_rank": 1, "rerank_rank": 6, "fusion_sco