INSERT INTO "aai"."askcontent_chat_turn" ("id", "org_id", "thread_id", "ordinal", "question", "answer", "evidence", "steps", "grounded", "unsupported_reason", "answered_by", "elapsed_ms", "error", "created_at", "updated_at") VALUES ('e7cede04-4440-463b-b40e-e67efbd1eae5', '9a76da8a-4934-4a60-838d-ca2bf689bd38', '45ba5f8c-6a84-4132-8da1-7847011c1bbb', 1, 'What are the options for help with auto loan payments?', 'If you''re having trouble with your auto loan payments, you have a few options for help:

- You can change your payment due date, as long as you''ve made your first payment, it''s your first due date change, and your account is current or no more than 10 days past due [4].
- You may be able to defer a payment, which pushes out your due date and extends the loan maturity date; you''ll need to call Wells Fargo to see if you''re eligible for a deferment [3].
- Wells Fargo can work with you on payment arrangements if you''re experiencing challenges [3].
- If you''re a servicemember, the Servicemembers Civil Relief Act (SCRA) may allow your interest rate to be adjusted to 6%, which could lower your payment; for more information, you can refer to the SCRA or call 1-877-254-9687 [5].', '{"trace": {"filters": {"spaces": ["WELLSFARGO_HELP_CENTER"], "doc_types": [], "labels_any": [], "principals": ["group:all-staff"], "labels_none": [], "updated_after": null, "updated_before": null}, "refusal": null, "channels": [{"top": ["https://www.wellsfargo.com/help/loans/auto-loans-faqs", "https://www.wellsfargo.com/help/loans", "https://www.wellsfargo.com/help/contact-us", "https://www.wellsfargo.com/help/home-lending", "https://www.wellsfargo.com/help/loans/personal-loan-faqs/?sub_channel=WEB&vendor_code=WF&linkloc=FNPLFAQ"], "hits": 16, "error": null, "channel": "pgp", "latency_ms": 871.3}, {"top": ["https://www.wellsfargo.com/help/loans", "https://www.wellsfargo.com/help/loans/auto-loans-faqs", "https://www.wellsfargo.com/help/checking-savings", "https://www.wellsfargo.com/help/credit-cards", "https://www.wellsfargo.com/help/home-lending"], "hits": 10, "error": null, "channel": "ecm", "latency_ms": 98.91}], "degraded": [], "phase_ms": {"prime": 0, "rerank": 1.1, "resolve": 0.2, "passages": 27.3, "candidates": 871.7, "resolve_batch": 98.3, "embed_question": 160.9}, "synonyms": {}, "total_ms": 1159.79, "plan_hash": "pln_471c28f3900a61bc", "spec_json": "{\"authority\":\"include_supporting\",\"channels\":[\"pgp\",\"ecm\"],\"diversity_by\":\"document\",\"doc_types\":[],\"filters\":[],\"freshness\":{\"as_of\":null,\"max_age_days\":null},\"intent\":\"lookup\",\"k_per_channel\":20,\"question\":\"What are the options for help with auto loan payments?\",\"scope_ref\":\"scope:cn-wells-fargo-help-centre:v1\",\"terms\":[]}", "candidates": [{"title": "Personal Loan Help | Wells Fargo", "doc_id": "https://www.wellsfargo.com/help/loans", "authority": "supporting", "cache_hit": true, "staleness": "unknown_age", "dropped_by": null, "parse_path":