INSERT INTO "aai"."askcontent_chat_turn" ("id", "org_id", "thread_id", "ordinal", "question", "answer", "evidence", "steps", "grounded", "unsupported_reason", "answered_by", "elapsed_ms", "error", "created_at", "updated_at") VALUES ('72912748-fd1b-4fb7-9626-cb3122125298', '9a76da8a-4934-4a60-838d-ca2bf689bd38', '45ba5f8c-6a84-4132-8da1-7847011c1bbb', 4, 'How do I set up Autopay again?', 'You can set up Autopay for your Wells Fargo auto loan to have your payment debited monthly from your checking or savings account[1]. Here are the ways to do it:

1. Sign on to your Wells Fargo online account[1].
2. Select your auto loan from the **Account Summary**[1].
3. Select **Set up Autopay**[1].

Alternatively, you can:
- Call Wells Fargo at 1-800-289-8004[1].
- Download the automatic loan payments authorization (PDF), complete the form, and return it by mail or fax[1].

