INSERT INTO "aai"."askcontent_chat_turn" ("id", "org_id", "thread_id", "ordinal", "question", "answer", "evidence", "steps", "grounded", "unsupported_reason", "answered_by", "elapsed_ms", "error", "created_at", "updated_at") VALUES ('1df9aa63-40a9-4507-b1e5-4f64135b9f94', '9a76da8a-4934-4a60-838d-ca2bf689bd38', '408fe0cc-6715-4d9a-9d75-359cb42bd290', 1, 'How do I find my routing or account numbers?', 'You can find your Wells Fargo routing and account numbers in several ways:

## Online

1. Sign on to Wells Fargo Online® and select the account you’re interested in [2].
2. For your routing number, select **Routing numbers** directly below the account name and after the account number [1].
3. For your full account number, select **Account** and the 4 numbers directly below the account name [2].

## On Your Account Statement

- Your account number is located at the top of your online or paper statement [1].

## On a Check

- Your account number is located along the bottom of your check, to the right of the routing number and to the left of the check number [3].
- The routing number is also found along the bottom of your check [3].

## By Phone

- If you don’t know your account number, you can call Wells Fargo at 1-800-869-3557, 24 hours a day, 7 days a week [3].

After you locate your routing or account numbers using any of these methods, you can use them for transactions such as direct deposit, wire transfers, or setting up payments.', '{"trace": {"filters": {"spaces": ["WELLSFARGO_HELP_CENTER"], "doc_types": [], "labels_any": [], "principals": ["group:all-staff"], "labels_none": [], "updated_after": null, "updated_before": null}, "refusal": null, "channels": [{"top": [], "hits": 0, "error": "timeout", "channel": "pgp", "latency_ms": 3000}, {"top": ["https://www.wellsfargo.com/help/routing-number", "https://www.wellsfargo.com/help/contact-us"], "hits": 2, "error": null, "channel": "ecm", "latency_ms": 175.32}], "degraded": ["pgp channel unavailable: timeout"], "phase_ms": {"prime": 214.3, "rerank": 681.4, "resolve": 0.1, "assemble": 0.7, "passages": 1.8, "candidates": 3263.7, "resolve_batch": 90.1, "embed_question": 500}, "synonyms": {}, "total_ms": 4752.7, "plan_hash": "pln_678b22d7ab6e295c", "spec_json": "{\"authority\":\"include_supporting\",\"channels\":[\"pgp\",\"ecm\"],\"diversity_by\":\"document\",\"doc_types\":[],\"filters\":[],\"freshness\":{\"as_of\":null,\"max_age_days\":null},\"intent\":\"lookup\",\"k_per_channel\":20,\"question\":\"How do I find my routing or account numbers?\",\"scope_ref\":\"scope:cn-wells-fargo-help-centre:v1\",\"terms\":[]}", "candidates": [{"title": "Routing & Account Number Information for Your Wells Fargo Accounts", "doc_id": "https://www.wellsfargo.com/help/routing-number", "authority": "supporting", "cache_hit": true, "staleness": "unknown_age", "dropped_by": null, "parse_path": "html_trafilatura", "resolution": "resolved", "drop_detail": null, "fusion_rank": 1, "rerank_rank": 3, "fusion_score": 0.016393, "rerank_score": 0.7, "channel_ranks": {"ecm": 1}, "parse_quality": {"warnings": [], "char_count": 0, "block_count": 0, "table_count": 0, "ocr_confidence": null, "text_yield_per_page": null}, "chunks_selected": 3}, {"title": "Wells Fargo Customer Service Contact Us Numbers | Wells Farg